const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const saskatchewan = ee.FeatureCollection('FAO/GAUL/2015/level1')
    .filter(ee.Filter.eq('ADM1_NAME', 'Saskatchewan'));

  const date = '2025-08-03';
  const startDate = ee.Date(date);
  const endDate = startDate.advance(1, 'day');

  // 2. Data Acquisition - Try VIIRS first (higher resolution)
  let fireCollection = ee.ImageCollection('NOAA/VIIRS/001/VNP14A1')
    .filterBounds(saskatchewan)
    .filterDate(startDate, endDate);

  let collectionSize = fireCollection.size().getInfo();
  console.log(`VIIRS Collection size for ${date}: ${collectionSize}`);

  // If no VIIRS data, try MODIS
  if (collectionSize === 0) {
    fireCollection = ee.ImageCollection('MODIS/006/MCD14DL')
      .filterBounds(saskatchewan)
      .filterDate(startDate, endDate);

    collectionSize = fireCollection.size().getInfo();
    console.log(`MODIS Collection size for ${date}: ${collectionSize}`);
  }

  // If still no data, try widening date range (±1 day)
  if (collectionSize === 0) {
    const widerStart = startDate.advance(-1, 'day');
    const widerEnd = endDate.advance(1, 'day');

    fireCollection = ee.ImageCollection('NOAA/VIIRS/001/VNP14A1')
      .filterBounds(saskatchewan)
      .filterDate(widerStart, widerEnd);

    collectionSize = fireCollection.size().getInfo();
    console.log(`VIIRS Collection size for ±1 day: ${collectionSize}`);
  }

  // If no data after fallbacks, output C1
  if (collectionSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Count fire pixels
  // Use 'FireMask' band where values 6-9 indicate fires (low to very high confidence)
  const fireMask = fireCollection.select('FireMask');

  // Create binary mask for fires (values >= 6)
  const fireBinary = fireMask.map(function(image) {
    return image.gte(6).selfMask();
  });

  // Count fire pixels over the region
  const fireCount = fireBinary.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: saskatchewan,
    scale: 1000,
    maxPixels: 1e9
  }).get('FireMask').getInfo();

  console.log(`Fire detections on ${date}: ${fireCount}`);

  // 4. Validation & Final Answer
  if (fireCount === null || fireCount === undefined || fireCount < 0) {
    console.log("<answer>C3</answer>");
  } else if (fireCount > 120) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
